export function buildInstallPrompt(config) {
  const repo = resolveRepo(config)
  const mirror = ORCHD_MIRROR_REPO
  const lines = [
    '请帮我用 orchd 接入当前项目。',
    '',
    '背景：这是用户从 DSH 的「orchd 任务」面板点击确认后注入的请求；面板本身是**只读**的，不会替你做安装。',
    '',
