    'master-unparsable': '任务定义文件 _master.json 存在但不是合法 JSON。',
    'master-unreadable': '任务定义文件存在但无法读取。',
    'definition-archived-unsupported': '任务定义似乎已被归档到外部文件，本版本不支持读取。',
